INSERT INTO items(item_id, title, description, img_path, price) VALUES
              (1, 'Проектор Vidda C3 Ultra', 'Проектор Vidda C3 Ultra RGB 4K трехцветный лазерный проектор 3200CVIA MT9681 MCL39 8+128 ГБ 0,9-1,5:1 оптический зум видео 3D Android Cinema проектор, DLP', 'images/vidda_c3_ultra.webp', 130000),
              (2, 'Hisense M2 PRO', '- Размер проекции 65-200 дюймов \n - Режим Auto Magic Al \n - Трехцветный лазер 110%BT.2020 \n - Оптический зум', 'images/hisense_m2_pro.png', 50000),
              (3, 'Hisense C2 Ultra', '- Яркость 3000 ANSI люменов \n - Проекция 65-300 дюймов \n - Оптический зум \n - Звук JBL 2.1 со встроенным сабвуфером', 'images/hisense_c2_ultra.png', 140000),
              (4, 'JMGO N5 Ultra Max', 'Проектор Трехцветный лазерный проектор JMGO N5 Ultra Max 4K 3840x2160 Qualas32 с разрешением ISO 6000 люмен, 8+ 128 ГБ, оптическим увеличением 0,88-1,7:1 для домашнего кинотеатра с видеоиграми', 'images/jmgo_n5_ulta_max.webp', 160000),
              (5, 'Dangbei Mars Pro 2', 'Откройте для себя невероятное качество изображения и современные технологии с проектором Dangbei Mars Pro 2 – это идеальный выбор для создания настоящего домашнего кинотеатра. Устройство сочетает в себе лазерную технологию, интеллектуальные функции и высокое разрешение, чтобы подарить вам по-настоящему захватывающий опыт просмотра.', 'images/dangbei_mars_pro_2.webp', 105000),
              (6, 'XGIMI Horizon S Pro', 'Превратите свою гостиную в гигантский 4K-кинотеатр с Dolby Vision и наслаждайтесь высочайшим качеством изображения прямо у себя дома.', 'images/xgimi_horizon_s_pro.png', 14990),
              (7, 'XGIMI RS 20 Ultra Max', 'XGIMI RS 20 Ultra Max оснащен новой трехцветной лазерной технологией, обеспечивающей сверхчеткое разрешение 4K и превосходную цветопередачу. Его яркость достигает 4500 люмен CVIA, обеспечивая четкое изображение даже днем, подходит для использования в хорошо освещенных помещениях, таких как гостиные.', 'images/xgimi_rs_20_ultra_max.webp', 180000)
